// Not in Agrona (LongHashSet is generated by Agrona's build and its test is not in the 2.6.1 sources): IntHashSet and
// LongHashSet against a JS Set model for seeded random operations, the paths IntHashSetTest does not reach (compact,
// copy, an uncached iterator, iterator misuse, constructor limits), and the long keys of LongHashSet (spec D5).
import { describe, expect, it } from 'vitest';
import { Hashing } from '../../../src/agrona/collections/Hashing.js';
import { IntHashSet } from '../../../src/agrona/collections/IntHashSet.js';
import { LongHashSet } from '../../../src/agrona/collections/LongHashSet.js';
import { IllegalArgumentException, IllegalStateException, Long } from '../../../src/agrona/jdk.js';
import { longHashCode, NoSuchElementException } from '../../../src/agrona/jdkUtil.js';
import { assertThrows } from '../../support/Assertions.js';
import { mulberry32 } from '../../support/Random.js';

function sorted(values: Iterable<number>): number[] {
    return [...values].sort((a, b) => a - b);
}

describe('HashSetsExtra', () => {
    it('compactChainMovesAnEntryThatWrappedPastTheEndBack', () => {
        const set = new IntHashSet(16);
        const mask = set.capacity() - 1;
        const atEnd: number[] = [];
        for (let v = 1; atEnd.length < 2; v++) {
            if (Hashing.hash(v, mask) === mask) atEnd.push(v);
        }
        const [a, b] = atEnd as [number, number];
        set.add(a);
        set.add(b);
        expect(set.remove(a)).toBe(true);
        expect(set.contains(b)).toBe(true);
        expect(set.size()).toBe(1);
    });

    it('resizesOnlyWhenTheSizePassesTheThreshold', () => {
        const set = new IntHashSet();
        const threshold = set.resizeThreshold();
        for (let i = 1; i <= threshold; i++) set.add(i);
        expect(set.capacity()).toBe(8);
        set.add(100);
        expect(set.capacity()).toBe(16);
    });

    it('compactUsesTheLoadFactor', () => {
        const set = new IntHashSet();
        for (let i = 1; i <= 12; i++) set.add(i);
        set.compact();
        expect(set.capacity()).toBe(32);
    });

    it('intHashSetAgreesWithASetModelForRandomOperations', () => {
        const random = mulberry32(0x5eed);
        const set = new IntHashSet(2);
        const model = new Set<number>();
        const bound = 600;

        for (let i = 0; i < 20_000; i++) {
            // a small range makes collisions, removals and the missing value (0) frequent
            const value = Math.floor(random() * bound) - bound / 2;
            switch (Math.floor(random() * 3)) {
                case 0:
                    expect(set.add(value)).toBe(!model.has(value));
                    model.add(value);
                    break;
                case 1:
                    expect(set.remove(value)).toBe(model.has(value));
                    model.delete(value);
                    break;
                default:
                    expect(set.contains(value)).toBe(model.has(value));
            }

            expect(set.size()).toBe(model.size);
            if (i % 997 === 0) {
                expect(sorted(set)).toEqual(sorted(model));
                expect(set.equals(model)).toBe(true);
            }
        }

        expect(sorted(set)).toEqual(sorted(model));
    });

    it('longHashSetAgreesWithASetModelForRandomOperationsOverTheWholeSafeRange', () => {
        const random = mulberry32(0xbeef);
        const set = new LongHashSet(2);
        const model = new Set<number>();
        const pool: number[] = [0, 1, -1, Long.MAX_VALUE, Long.MIN_VALUE, 2 ** 32, -(2 ** 32), 2 ** 31, 2 ** 32 - 1];
        for (let i = 0; i < 300; i++) {
            pool.push(Math.floor((random() * 2 - 1) * Long.MAX_VALUE));
        }

        for (let i = 0; i < 20_000; i++) {
            const value = pool[Math.floor(random() * pool.length)]!;
            switch (Math.floor(random() * 3)) {
                case 0:
                    expect(set.add(value)).toBe(!model.has(value));
                    model.add(value);
                    break;
                case 1:
                    expect(set.remove(value)).toBe(model.has(value));
                    model.delete(value);
                    break;
                default:
                    expect(set.contains(value)).toBe(model.has(value));
            }

            expect(set.size()).toBe(model.size);
        }

        expect(sorted(set)).toEqual(sorted(model));
        expect(set.equals(model)).toBe(true);
        let hash = 0;
        for (const v of model) {
            hash = (hash + longHashCode(v)) | 0;
        }
        expect(set.hashCode()).toBe(hash);
    });

    it('longHashSetIteratorRemovesEveryElementWhileIterating', () => {
        const set = new LongHashSet();
        const values = [0, 5, -5, 2 ** 40, -(2 ** 40), 2 ** 52, 12345678901];
        for (const v of values) {
            set.add(v);
        }

        const seen: number[] = [];
        for (const it = set.iterator(); it.hasNext();) {
            seen.push(it.nextValue());
            it.remove();
        }

        expect(sorted(seen)).toEqual(sorted(values));
        expect(set.size()).toBe(0);
        for (const v of values) {
            expect(set.contains(v)).toBe(false);
        }
    });

    it('longHashSetRejectsAnUnsafeValueAndFindsNone', () => {
        const set = new LongHashSet();
        set.add(7);

        for (const bad of [Long.MAX_VALUE + 2, -(2 ** 53) - 2, 1.5, NaN, Infinity]) {
            assertThrows(RangeError, () => set.add(bad));
            expect(set.contains(bad)).toBe(false);
            expect(set.remove(bad)).toBe(false);
        }

        expect(sorted(set)).toEqual([7]);
        expect(set.size()).toBe(1);
    });

    it('longHashSetStoresMinusZeroAsTheMissingValue', () => {
        const set = new LongHashSet();

        expect(set.add(-0)).toBe(true);
        expect(set.contains(0)).toBe(true);
        expect(set.add(0)).toBe(false);
        expect(Object.is([...set][0], 0)).toBe(true);
        expect(set.remove(-0)).toBe(true);
        expect(set.size()).toBe(0);
    });

    it('longHashSetEqualsNeverMatchesANonLongElement', () => {
        const set = new LongHashSet();
        set.add(1);
        set.add(2);

        expect(set.equals(new Set([1, 2]))).toBe(true);
        expect(set.equals(new Set([1, 2.5]))).toBe(false);
        expect(set.equals(new Set([1, 'x']))).toBe(false);
        expect(set.equals(new Set([1, null]))).toBe(false);
        expect(set.equals([1, 2])).toBe(false);
        expect(set.equals(null)).toBe(false);
    });

    it('compactRehashesToACapacityJustLargerThanTheSizeAndKeepsEveryValue', () => {
        const set = new IntHashSet();
        for (let i = 1; i <= 1000; i++) {
            set.add(i);
        }
        for (let i = 1; i <= 990; i++) {
            set.remove(i);
        }
        const before = set.capacity();

        set.compact();

        expect(set.capacity()).toBeLessThan(before);
        expect(set.capacity()).toBe(16);
        expect(sorted(set)).toEqual([991, 992, 993, 994, 995, 996, 997, 998, 999, 1000]);
    });

    it('copyRequiresTheSameCapacityAndCopiesTheMissingValue', () => {
        const a = new IntHashSet(16);
        const b = new IntHashSet(64);
        assertThrows(IllegalArgumentException, () => a.copy(b));

        const c = new IntHashSet(16);
        c.add(0);
        c.add(9);
        a.copy(c);
        expect(a.equals(c)).toBe(true);
        expect(a.contains(0)).toBe(true);
    });

    it('anUncachedIteratorIsANewObjectEachTimeAndACachedOneIsReused', () => {
        const uncached = new IntHashSet(8, 0.5, false);
        const cached = new IntHashSet(8, 0.5, true);
        uncached.add(1);
        cached.add(1);

        expect(uncached.iterator()).not.toBe(uncached.iterator());
        expect(cached.iterator()).toBe(cached.iterator());
    });

    it('iteratorMisuseThrows', () => {
        const set = new IntHashSet();
        set.add(1);

        const it = set.iterator();
        assertThrows(IllegalStateException, () => it.remove());
        expect(it.remaining()).toBe(1);
        expect(it.nextValue()).toBe(1);
        expect(it.remaining()).toBe(0);
        it.remove();
        assertThrows(IllegalStateException, () => it.remove());
        assertThrows(NoSuchElementException, () => it.nextValue());
    });

    it('constructorValidatesTheLoadFactorAndRoundsTheCapacityUp', () => {
        assertThrows(IllegalArgumentException, () => new IntHashSet(8, 0.05));
        assertThrows(IllegalArgumentException, () => new IntHashSet(8, 0.95));
        assertThrows(IllegalArgumentException, () => new LongHashSet(8, 0.95));

        const set = new IntHashSet(9, 0.5);
        expect(set.capacity()).toBe(16);
        expect(set.resizeThreshold()).toBe(8);
        expect(set.loadFactor()).toBe(0.5);
        expect(new IntHashSet(1).capacity()).toBe(IntHashSet.DEFAULT_INITIAL_CAPACITY);
    });

    it('differenceIsNullForEqualSetsAndAddAllReportsOnlyRealChanges', () => {
        const a = new LongHashSet();
        const b = new LongHashSet();
        a.addAll([1, 2 ** 40, 0]);
        b.addAll([0, 1, 2 ** 40]);

        expect(a.difference(b)).toBeNull();
        expect(a.addAll(b)).toBe(false);
        expect(a.removeAll(new LongHashSet())).toBe(false);
        expect(a.retainAll(b)).toBe(false);
        expect(a.retainAll([1])).toBe(true);
        expect(sorted(a)).toEqual([1]);
    });
});
